translated_query:
SELECT  ?paper
WHERE
  { ?paper   a                     <http://conference#Conference_contribution> ;
             <http://conference#has_authors>  ?author ;
             a                     <http://conference#Written_contribution> .
    ?author  a                     <http://conference#Regular_author> ;
             a                     <http://conference#Active_conference_participant> .
    ?paper   <http://cmt#assignedTo>  ?rev
  }

SELECT DISTINCT  ?w ?e
WHERE
  { ?w  a                     <http://conference#Workshop> ;
        <http://confOf#hasAdministrativeEvent>  ?e
    FILTER strstarts(str(?w), "http://confOf-instances#workshop-")
  }

relaxed_query:
SELECT DISTINCT  ?p
WHERE {
  ?p a <http://conference#Regular_author> .
  ?paper a <http://conference#Conference_contribution> .
  ?p <http://conference#contributes> ?paper .
  OPTIONAL { ?p <http://conference#Reviewed_contribution> ?review . }
}

translated_query:
SELECT DISTINCT  ?paper
WHERE
  { ?paper  a                     <http://conference#Paper> ;
            <http://conference#has_authors>  ?author
    FILTER regex(str(?paper), "^http://confOf-instances#paper")
  }
